def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    # Check that all classes are valid
    for c in classes:
        if not isinstance(c, type):
            raise ValueError("Invalid class provided")

    # Sort classes by inheritance order
    sorted_classes = sorted(classes, key=lambda c: len(c.__mro__))

    # Reduce to minimal list of bases
    reduced_classes = []
    for c in sorted_classes:
