def get_nested_custom_and_control_args(self, args):
    control_args, nested_args, custom_args = {}, {}, {}
    for k, v in args.items():
        if k in self.ARGUMENT_SPEC.keys():
            nested_args[k] = v
        elif k.startswith('--control-'):
            control_args[k.replace('--control-', '')] = v
